   {
    "label": "Page 4",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">Areas We Treat</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">Embolization can be used for pain in many joints and tendons. The procedure name depends on the area treated.</p>\n<div style=\"display: grid; grid-template-columns: 210px 1fr; gap: 24px; align-items: start\">\n<div><svg viewBox=\"20 0 260 530\" role=\"img\" aria-label=\"Outline of a body with numbered markers at the shoulder, hip, knee, hand, wrist, ankle, heel and lower back\" style=\"width: 100%; height: 470px; display: block\"><circle cx=\"160\" cy=\"48\" r=\"30\" fill=\"#D9E1F2\"/>\n<path d=\"M118 92 Q160 80 202 92 L214 250 Q160 262 106 250 Z\" fill=\"#D9E1F2\"/>\n<path d=\"M118 96 Q96 104 92 130 L70 268 Q66 286 78 288 Q90 290 92 270 L112 150 Z\" fill=\"#D9E1F2\"/>\n<path d=\"M202 96 Q224 104 228 130 L250 268 Q254 286 242 288 Q230 290 228 270 L208 150 Z\" fill=\"#D9E1F2\"/>\n<path d=\"M108 250 Q132 262 158 256 L152 470 Q150 492 130 490 Q118 488 120 466 Z\" fill=\"#D9E1F2\"/>\n<path d=\"M212 250 Q188 262 162 256 L168 470 Q170 492 190 490 Q202 488 200 466 Z\" fill=\"#D9E1F2\"/>\n<path d=\"M118 486 L150 486 L150 504 L104 506 Q98 498 118 486 Z\" fill=\"#D9E1F2\"/>\n<path d=\"M170 486 L202 486 Q222 498 216 506 L170 504 Z\" fill=\"#D9E1F2\"/><circle cx=\"108\" cy=\"112\" r=\"15\" fill=\"#C8231E\" stroke=\"#FFFEFB\" stroke-width=\"3\"/><text x=\"108\" y=\"117\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">1</text><circle cx=\"132\" cy=\"250\" r=\"15\" fill=\"#C8231E\" stroke=\"#FFFEFB\" stroke-width=\"3\"/><text x=\"132\" y=\"255\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">2</text><circle cx=\"140\" cy=\"370\" r=\"15\" fill=\"#C8231E\" stroke=\"#FFFEFB\" stroke-width=\"3\"/><text x=\"140\" y=\"375\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">3</text><circle cx=\"80\" cy=\"300\" r=\"15\" fill=\"#C8231E\" stroke=\"#FFFEFB\" stroke-width=\"3\"/><text x=\"80\" y=\"305\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">4</text><circle cx=\"84\" cy=\"262\" r=\"15\" fill=\"#C8231E\" stroke=\"#FFFEFB\" stroke-width=\"3\"/><text x=\"84\" y=\"267\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">5</text><circle cx=\"144\" cy=\"478\" r=\"15\" fill=\"#C8231E\" stroke=\"#FFFEFB\" stroke-width=\"3\"/><text x=\"144\" y=\"483\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">6</text><circle cx=\"196\" cy=\"500\" r=\"15\" fill=\"#C8231E\" stroke=\"#FFFEFB\" stroke-width=\"3\"/><text x=\"196\" y=\"505\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">7</text><circle cx=\"160\" cy=\"208\" r=\"15\" fill=\"#C8231E\" stroke=\"#FFFEFB\" stroke-width=\"3\"/><text x=\"160\" y=\"213\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">8</text></svg></div>\n<div style=\"display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px\"><div style=\"display: flex; gap: 14px; align-items: flex-start; background: #F7F6F2; border-radius: 12px; padding: 14px 16px\"><div style=\"width: 30px; height: 30px; flex: none; border-radius: 50%; background: #C8231E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">1</div><div style=\"display: flex; flex-direction: column; gap: 3px; min-width: 0\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Shoulder</p><p style=\"margin: 0; font-size: 14.5px; line-height: 1.4\">Frozen shoulder, rotator cuff tendon problems and shoulder arthritis</p><p style=\"margin: 0; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: #C8231E\">TAME</p></div></div><div style=\"display: flex; gap: 14px; align-items: flex-start; background: #F7F6F2; border-radius: 12px; padding: 14px 16px\"><div style=\"width: 30px; height: 30px; flex: none; border-radius: 50%; background: #C8231E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">2</div><div style=\"display: flex; flex-direction: column; gap: 3px; min-width: 0\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Hip</p><p style=\"margin: 0; font-size: 14.5px; line-height: 1.4\">Arthritis pain in people not ready for, or not able to have, hip replacement</p><p style=\"margin: 0; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: #C8231E\">TAME</p></div></div><div style=\"display: flex; gap: 14px; align-items: flex-start; background: #F7F6F2; border-radius: 12px; padding: 14px 16px\"><div style=\"width: 30px; height: 30px; flex: none; border-radius: 50%; background: #C8231E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">3</div><div style=\"display: flex; flex-direction: column; gap: 3px; min-width: 0\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Knee</p><p style=\"margin: 0; font-size: 14.5px; line-height: 1.4\">Mild to moderate osteoarthritis, and some cases of pain after knee replacement</p><p style=\"margin: 0; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: #C8231E\">GAE</p></div></div><div style=\"display: flex; gap: 14px; align-items: flex-start; background: #F7F6F2; border-radius: 12px; padding: 14px 16px\"><div style=\"width: 30px; height: 30px; flex: none; border-radius: 50%; background: #C8231E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">4</div><div style=\"display: flex; flex-direction: column; gap: 3px; min-width: 0\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Hand &amp; thumb</p><p style=\"margin: 0; font-size: 14.5px; line-height: 1.4\">Arthritis in the finger joints and at the base of the thumb</p><p style=\"margin: 0; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: #C8231E\">TAME</p></div></div><div style=\"display: flex; gap: 14px; align-items: flex-start; background: #F7F6F2; border-radius: 12px; padding: 14px 16px\"><div style=\"width: 30px; height: 30px; flex: none; border-radius: 50%; background: #C8231E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">5</div><div style=\"display: flex; flex-direction: column; gap: 3px; min-width: 0\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Wrist</p><p style=\"margin: 0; font-size: 14.5px; line-height: 1.4\">Arthritis and long-lasting wrist pain</p><p style=\"margin: 0; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: #C8231E\">TAME</p></div></div><div style=\"display: flex; gap: 14px; align-items: flex-start; background: #F7F6F2; border-radius: 12px; padding: 14px 16px\"><div style=\"width: 30px; height: 30px; flex: none; border-radius: 50%; background: #C8231E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">6</div><div style=\"display: flex; flex-direction: column; gap: 3px; min-width: 0\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Ankle</p><p style=\"margin: 0; font-size: 14.5px; line-height: 1.4\">Arthritis and long-lasting ankle pain</p><p style=\"margin: 0; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: #C8231E\">TAME</p></div></div><div style=\"display: flex; gap: 14px; align-items: flex-start; background: #F7F6F2; border-radius: 12px; padding: 14px 16px\"><div style=\"width: 30px; height: 30px; flex: none; border-radius: 50%; background: #C8231E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">7</div><div style=\"display: flex; flex-direction: column; gap: 3px; min-width: 0\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Heel</p><p style=\"margin: 0; font-size: 14.5px; line-height: 1.4\">Plantar fasciitis that hasn’t improved with stretching, shoes or injections</p><p style=\"margin: 0; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: #C8231E\">PFE</p></div></div><div style=\"display: flex; gap: 14px; align-items: flex-start; background: #F7F6F2; border-radius: 12px; padding: 14px 16px\"><div style=\"width: 30px; height: 30px; flex: none; border-radius: 50%; background: #C8231E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">8</div><div style=\"display: flex; flex-direction: column; gap: 3px; min-width: 0\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Lower back</p><p style=\"margin: 0; font-size: 14.5px; line-height: 1.4\">Certain types of long-lasting lower back pain; ask whether you may be a candidate</p><p style=\"margin: 0; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: #C8231E\">Ask your specialist</p></div></div></div>\n</div>\n<p style=\"margin: 0; font-size: 13px; line-height: 1.4; color: #4A5568\"><b>GAE</b>: genicular artery embolization. <b>TAME</b>: transcatheter arterial micro-embolization. <b>PFE</b>: plantar fasciitis embolization. Not every patient is a candidate. Your specialist will review your symptoms and imaging to decide whether a procedure may help.</p>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-start; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">4</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 5",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">Evaluating Your Joint Pain</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">Before any treatment, your specialist will learn about your pain and look for its cause. This helps make sure a procedure is right for you.</p>\n<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start\"><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Your Medical History</h2><p style=\"margin: 0; font-size: 16px; line-height: 1.5\">Your specialist will ask about:</p><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 6px; font-size: 16px; line-height: 1.45\"><li>Where it hurts, and for how long</li><li>What makes the pain better or worse</li><li>Treatments you’ve tried, such as medicine, therapy, injections or surgery</li><li>Other health problems, such as diabetes, kidney disease or poor circulation</li><li>Medicines you take, especially blood thinners</li><li>Allergies, especially to X-ray contrast dye or iodine</li></ul></div><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><img src=\"assets/photo-shoulder.jpg\" alt=\"An older man holds his sore shoulder\" style=\"width: 100%; height: 200px; object-fit: cover; object-position: 35% 40%; border-radius: 12px; display: block\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Your Physical Exam</h2><p style=\"margin: 0; font-size: 16px; line-height: 1.5\">Your specialist checks the painful area for swelling, tenderness and how well it moves, and may check the pulses in your arms or legs.</p><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Imaging Tests</h2><p style=\"margin: 0; font-size: 16px; line-height: 1.5\">X-rays show how much cartilage has worn away. An MRI or ultrasound may be used to look at tendons and the joint lining. Bring any recent imaging to your visit.</p></div></div>\n<div style=\"background: #F7F6F2; border-top: 5px solid #16306E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Rating Your Pain</h2><p style=\"margin: 0; font-size: 16px; line-height: 1.5\">You may be asked to rate your pain from 0 to 10 and answer a few questions about daily activities. Doing this again after treatment helps you and your doctor track your progress.</p><svg viewBox=\"0 0 704 92\" role=\"img\" aria-label=\"0 to 10 pain rating scale from no pain to worst pain\" style=\"width: 100%; height: 92px; display: block\"><rect x=\"0\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#E3F1E6\"/><text x=\"30\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #1B2440\">0</text><rect x=\"64\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#CFE8D4\"/><text x=\"94\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #1B2440\">1</text><rect x=\"128\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#E6EFC4\"/><text x=\"158\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #1B2440\">2</text><rect x=\"192\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#F3EDB5\"/><text x=\"222\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #1B2440\">3</text><rect x=\"256\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#F7E2A0\"/><text x=\"286\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #1B2440\">4</text><rect x=\"320\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#F6CF8A\"/><text x=\"350\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #1B2440\">5</text><rect x=\"384\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#F2B277\"/><text x=\"414\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #1B2440\">6</text><rect x=\"448\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#E88B62\"/><text x=\"478\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #FFFFFF\">7</text><rect x=\"512\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#DC6650\"/><text x=\"542\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #FFFFFF\">8</text><rect x=\"576\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#CE4436\"/><text x=\"606\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #FFFFFF\">9</text><rect x=\"640\" y=\"0\" width=\"60\" height=\"52\" rx=\"8\" fill=\"#B92A22\"/><text x=\"670\" y=\"34\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; fill: #FFFFFF\">10</text><text x=\"30\" y=\"80\" text-anchor=\"middle\" style=\"font-family: Public Sans, sans-serif; font-size: 13px; fill: #1B2440\">No pain</text><text x=\"350\" y=\"80\" text-anchor=\"middle\" style=\"font-family: Public Sans, sans-serif; font-size: 13px; fill: #1B2440\">Moderate</text><text x=\"674\" y=\"80\" text-anchor=\"middle\" style=\"font-family: Public Sans, sans-serif; font-size: 13px; fill: #1B2440\">Worst pain</text></svg></div>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-end; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">5</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 6",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">Your Treatment Plan</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">After your evaluation, you and your specialist will make a plan together. Treatment usually starts with the simplest options.</p>\n<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start\"><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Treatment Options</h2><div style=\"display: flex; flex-direction: column; gap: 8px\"><div style=\"display: flex; align-items: center; gap: 14px; margin-left: 0px; background: #F7F6F2; color: #1B2440; border-radius: 10px; padding: 10px 14px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 20px; width: 22px; flex: none; color: #C8231E\">1</span><span style=\"display: flex; flex-direction: column; gap: 2px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 16px\">Self-care</span><span style=\"font-size: 13.5px; line-height: 1.35; color: #4A5568\">Activity changes, weight management, heat or ice</span></span></div><div style=\"display: flex; align-items: center; gap: 14px; margin-left: 14px; background: #F7F6F2; color: #1B2440; border-radius: 10px; padding: 10px 14px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 20px; width: 22px; flex: none; color: #C8231E\">2</span><span style=\"display: flex; flex-direction: column; gap: 2px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 16px\">Physical therapy</span><span style=\"font-size: 13.5px; line-height: 1.35; color: #4A5568\">Exercises to build strength and flexibility</span></span></div><div style=\"display: flex; align-items: center; gap: 14px; margin-left: 28px; background: #F7F6F2; color: #1B2440; border-radius: 10px; padding: 10px 14px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 20px; width: 22px; flex: none; color: #C8231E\">3</span><span style=\"display: flex; flex-direction: column; gap: 2px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 16px\">Medicine</span><span style=\"font-size: 13.5px; line-height: 1.35; color: #4A5568\">Pain relievers and anti-inflammatory medicines</span></span></div><div style=\"display: flex; align-items: center; gap: 14px; margin-left: 42px; background: #F7F6F2; color: #1B2440; border-radius: 10px; padding: 10px 14px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 20px; width: 22px; flex: none; color: #C8231E\">4</span><span style=\"display: flex; flex-direction: column; gap: 2px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 16px\">Injections</span><span style=\"font-size: 13.5px; line-height: 1.35; color: #4A5568\">Steroid or gel injections into the joint</span></span></div><div style=\"display: flex; align-items: center; gap: 14px; margin-left: 56px; background: #16306E; color: #FFFFFF; border-radius: 10px; padding: 10px 14px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 20px; width: 22px; flex: none; color: #F2A7A3\">5</span><span style=\"display: flex; flex-direction: column; gap: 2px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 16px\">Embolization</span><span style=\"font-size: 13.5px; line-height: 1.35; color: #D9E1F2\">Minimally invasive, outpatient procedure</span></span></div><div style=\"display: flex; align-items: center; gap: 14px; margin-left: 70px; background: #F7F6F2; color: #1B2440; border-radius: 10px; padding: 10px 14px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 20px; width: 22px; flex: none; color: #C8231E\">6</span><span style=\"display: flex; flex-direction: column; gap: 2px\"><span style=\"font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 16px\">Surgery</span><span style=\"font-size: 13.5px; line-height: 1.35; color: #4A5568\">Such as joint replacement, for severe arthritis</span></span></div></div></div><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Is Embolization Right for Me?</h2><p style=\"margin: 0; font-size: 16px; line-height: 1.5\">You may be a candidate if you:</p><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 5px; font-size: 15.5px; line-height: 1.45\"><li>Have had joint or tendon pain for 3 months or more</li><li>Haven’t found enough relief with medicine, therapy or injections</li><li>Have arthritis or inflammation seen on imaging</li><li>Aren’t ready for, can’t have, or want to delay surgery</li></ul><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #C8231E\">It May Not Be Right If You Have</h2><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 4px; font-size: 15.5px; line-height: 1.45\"><li>An active infection</li><li>Severe arthritis better treated with joint replacement</li><li>A severe allergy to contrast dye that can’t be managed</li><li>Advanced kidney disease or a bleeding disorder</li><li>Serious blockages in the arteries of the arm or leg</li><li>Pregnancy</li></ul></div></div>\n<div style=\"background: #F7F6F2; border-top: 5px solid #16306E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Questions to Ask Your Doctor</h2><div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 24px; align-items: start\"><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 4px; font-size: 15.5px; line-height: 1.45\"><li>Am I a good candidate, and why?</li><li>What results can I realistically expect?</li><li>What are the risks for someone like me?</li></ul><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 4px; font-size: 15.5px; line-height: 1.45\"><li>What other treatments could I try first?</li><li>Will my insurance cover it, and what will I pay?</li></ul></div></div>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-start; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">6</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 7",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">How Embolization Works</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">Embolization is done by an interventional specialist, a doctor trained to treat problems inside blood vessels using small tubes and X-ray guidance.</p>\n<div style=\"display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px\"><svg viewBox=\"0 0 210 150\" role=\"img\" aria-label=\"Catheter reaches the small artery feeding inflamed tissue\" style=\"width: 100%; height: 140px; display: block\"><rect width=\"210\" height=\"150\" rx=\"12\" fill=\"#F7F6F2\"/>\n<ellipse cx=\"172\" cy=\"84\" rx=\"36\" ry=\"46\" fill=\"#C8231E\" opacity=\"0.55\"/>\n<path d=\"M0 78 L150 78\" stroke=\"#C8231E\" stroke-width=\"10\" stroke-linecap=\"round\" opacity=\".85\"/>\n<path d=\"M150 78 C160 60 172 66 178 52 M150 78 C168 76 176 90 192 84 M150 78 C162 96 150 106 164 118 M170 70 C182 74 186 62 196 64 M168 104 C180 100 186 112 196 106\" stroke=\"#C8231E\" stroke-width=\"2\" fill=\"none\" opacity=\"1\"/><path d=\"M0 78 L112 78\" stroke=\"#2F6FD6\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n<circle cx=\"22\" cy=\"22\" r=\"14\" fill=\"#16306E\"/><text x=\"22\" y=\"27\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">1</text></svg><svg viewBox=\"0 0 210 150\" role=\"img\" aria-label=\"Tiny particles flow into the extra vessels\" style=\"width: 100%; height: 140px; display: block\"><rect width=\"210\" height=\"150\" rx=\"12\" fill=\"#F7F6F2\"/>\n<ellipse cx=\"172\" cy=\"84\" rx=\"36\" ry=\"46\" fill=\"#C8231E\" opacity=\"0.55\"/>\n<path d=\"M0 78 L150 78\" stroke=\"#C8231E\" stroke-width=\"10\" stroke-linecap=\"round\" opacity=\".85\"/>\n<path d=\"M150 78 C160 60 172 66 178 52 M150 78 C168 76 176 90 192 84 M150 78 C162 96 150 106 164 118 M170 70 C182 74 186 62 196 64 M168 104 C180 100 186 112 196 106\" stroke=\"#C8231E\" stroke-width=\"2\" fill=\"none\" opacity=\"1\"/><path d=\"M0 78 L112 78\" stroke=\"#2F6FD6\" stroke-width=\"4\" stroke-linecap=\"round\"/><circle cx=\"124\" cy=\"78\" r=\"3\" fill=\"#16306E\"/><circle cx=\"136\" cy=\"76\" r=\"3\" fill=\"#16306E\"/><circle cx=\"148\" cy=\"80\" r=\"3\" fill=\"#16306E\"/><circle cx=\"158\" cy=\"70\" r=\"3\" fill=\"#16306E\"/><circle cx=\"164\" cy=\"90\" r=\"3\" fill=\"#16306E\"/><circle cx=\"172\" cy=\"64\" r=\"3\" fill=\"#16306E\"/><circle cx=\"180\" cy=\"86\" r=\"3\" fill=\"#16306E\"/><circle cx=\"160\" cy=\"108\" r=\"3\" fill=\"#16306E\"/>\n<circle cx=\"22\" cy=\"22\" r=\"14\" fill=\"#16306E\"/><text x=\"22\" y=\"27\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">2</text></svg><svg viewBox=\"0 0 210 150\" role=\"img\" aria-label=\"Blood flow to the inflamed tissue is reduced\" style=\"width: 100%; height: 140px; display: block\"><rect width=\"210\" height=\"150\" rx=\"12\" fill=\"#F7F6F2\"/>\n<ellipse cx=\"172\" cy=\"84\" rx=\"36\" ry=\"46\" fill=\"#C8231E\" opacity=\"0.2\"/>\n<path d=\"M0 78 L150 78\" stroke=\"#C8231E\" stroke-width=\"10\" stroke-linecap=\"round\" opacity=\".85\"/>\n<path d=\"M150 78 C160 60 172 66 178 52 M150 78 C168 76 176 90 192 84 M150 78 C162 96 150 106 164 118 M170 70 C182 74 186 62 196 64 M168 104 C180 100 186 112 196 106\" stroke=\"#C8231E\" stroke-width=\"2\" fill=\"none\" opacity=\"0.35\"/>\n<circle cx=\"22\" cy=\"22\" r=\"14\" fill=\"#16306E\"/><text x=\"22\" y=\"27\" text-anchor=\"middle\" style=\"font-family: Montserrat, sans-serif; font-weight: 800; font-size: 14px; fill: #FFFFFF\">3</text></svg></div>\n<div style=\"display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; margin-top: -8px\"><p style=\"margin: 0; font-size: 13px; line-height: 1.4; color: #4A5568\">The catheter reaches a small artery feeding the inflamed tissue.</p><p style=\"margin: 0; font-size: 13px; line-height: 1.4; color: #4A5568\">Tiny particles flow into the extra vessels.</p><p style=\"margin: 0; font-size: 13px; line-height: 1.4; color: #4A5568\">Blood flow to the inflamed tissue is reduced.</p></div>\n<div style=\"display: flex; flex-direction: column; gap: 14px\"><div style=\"display: flex; gap: 14px\"><span style=\"width: 32px; height: 32px; flex: none; border-radius: 50%; background: #16306E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">1</span><div style=\"display: flex; flex-direction: column; gap: 3px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">A small puncture</p><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Your specialist numbs the skin and places a thin, flexible tube called a catheter into an artery, usually in the wrist or the top of the thigh.</p></div></div><div style=\"display: flex; gap: 14px\"><span style=\"width: 32px; height: 32px; flex: none; border-radius: 50%; background: #16306E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">2</span><div style=\"display: flex; flex-direction: column; gap: 3px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Guided by X-ray</p><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Using live X-ray and contrast dye, the catheter is steered to the small arteries that feed the inflamed area.</p></div></div><div style=\"display: flex; gap: 14px\"><span style=\"width: 32px; height: 32px; flex: none; border-radius: 50%; background: #16306E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">3</span><div style=\"display: flex; flex-direction: column; gap: 3px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Tiny particles</p><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Microscopic particles are released to reduce blood flow in the extra vessels. Other arteries keep supplying blood to the bone and surrounding tissue.</p></div></div><div style=\"display: flex; gap: 14px\"><span style=\"width: 32px; height: 32px; flex: none; border-radius: 50%; background: #16306E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 15px\">4</span><div style=\"display: flex; flex-direction: column; gap: 3px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">All done</p><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">The catheter is removed, and pressure or a small closure device seals the puncture. No stitches are needed.</p></div></div></div>\n<div style=\"display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px\"><div style=\"background: #16306E; color: #FFFFFF; border-radius: 12px; padding: 14px 16px; display: flex; flex-direction: column; gap: 3px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 16px\">Outpatient</p><p style=\"margin: 0; font-size: 13.5px; color: #D9E1F2\">Home the same day</p></div><div style=\"background: #16306E; color: #FFFFFF; border-radius: 12px; padding: 14px 16px; display: flex; flex-direction: column; gap: 3px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 16px\">Usually 1 to 2 hours</p><p style=\"margin: 0; font-size: 13.5px; color: #D9E1F2\">For the procedure itself</p></div><div style=\"background: #16306E; color: #FFFFFF; border-radius: 12px; padding: 14px 16px; display: flex; flex-direction: column; gap: 3px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 16px\">Relaxing medicine</p><p style=\"margin: 0; font-size: 13.5px; color: #D9E1F2\">You stay awake but comfortable</p></div><div style=\"background: #16306E; color: #FFFFFF; border-radius: 12px; padding: 14px 16px; display: flex; flex-direction: column; gap: 3px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 16px\">No incision</p><p style=\"margin: 0; font-size: 13.5px; color: #D9E1F2\">Just a small puncture</p></div></div>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-end; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">7</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 8",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">Genicular Artery Embolization (GAE)</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">GAE treats knee pain caused by osteoarthritis. It targets the genicular arteries, the small blood vessels that supply the lining of the knee.</p>\n<figure style=\"margin: 0; background: #FFFFFF; border: 1px solid #E2DED4; border-radius: 14px; padding: 12px 12px 10px; display: flex; flex-direction: column; gap: 6px\"><img src=\"assets/render-knee.png\" alt=\"Illustration of the knee joint with inflamed blood vessels around the joint highlighted in red\" style=\"width: 100%; height: 296px; object-fit: contain; object-position: 50% 50%; display: block\"><p style=\"margin: 0; font-size: 13px; line-height: 1.4; color: #4A5568; text-align: center\">Inflamed tissue and the small blood vessels feeding it are shown in red.</p></figure>\n<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start\"><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Who May Benefit</h2><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 5px; font-size: 15.5px; line-height: 1.45\"><li>Mild to moderate knee osteoarthritis with ongoing pain</li><li>Pain that hasn’t improved after 3 months of medicine, therapy or injections</li><li>People not ready for, or not able to have, knee replacement</li><li>Some people with ongoing pain after knee replacement</li></ul></div><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">How It Works</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">The catheter is usually placed in an artery at the top of the thigh. Contrast dye maps the genicular arteries and shows areas of extra blood flow, which often match where your knee hurts. Particles are then released into those small branches.</p></div></div>\n<div style=\"background: #F7F6F2; border-top: 5px solid #16306E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">What the Research Shows</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">GAE is a newer procedure. Most studies so far have been small, and many had no comparison group. Studies comparing GAE with a placebo (sham) procedure have had mixed results, and larger trials are under way. Results vary from person to person.</p></div>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-start; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">8</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 9",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">TAME for the Shoulder &amp; Hip</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">Transcatheter arterial micro-embolization (TAME) uses the same approach as GAE to treat long-lasting pain from inflammation in other joints and tendons.</p>\n<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start\"><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><figure style=\"margin: 0; background: #FFFFFF; border: 1px solid #E2DED4; border-radius: 14px; padding: 12px 12px 10px; display: flex; flex-direction: column; gap: 6px\"><img src=\"assets/render-shoulder.png\" alt=\"Illustration of the shoulder joint with the inflamed area highlighted in red\" style=\"width: 100%; height: 172px; object-fit: cover; object-position: 50% 18%; display: block\"></figure><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Shoulder</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Conditions that may be treated:</p><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 4px; font-size: 15.5px; line-height: 1.45\"><li>Frozen shoulder (adhesive capsulitis)</li><li>Rotator cuff tendon problems</li><li>Shoulder arthritis</li></ul><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">The catheter is usually placed in an artery at the wrist. Particles go to the small vessels that feed the inflamed lining or tendon. The goal is less pain, including pain at night, and easier movement.</p></div><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><figure style=\"margin: 0; background: #FFFFFF; border: 1px solid #E2DED4; border-radius: 14px; padding: 12px 12px 10px; display: flex; flex-direction: column; gap: 6px\"><img src=\"assets/render-hip.png\" alt=\"Illustration of the hip joint with inflamed blood vessels highlighted in red\" style=\"width: 100%; height: 172px; object-fit: cover; object-position: 45% 22%; display: block\"></figure><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Hip</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">TAME may help people with arthritis-related hip pain who aren’t ready for, or can’t have, hip replacement.</p><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">The catheter is usually placed in an artery at the top of the thigh. Particles go to the small arteries around the lining of the hip joint.</p><div style=\"background: #F7F6F2; border-top: 5px solid #C8231E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Good to Know</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Research on TAME for the shoulder and hip is at an earlier stage than for the knee, and studies so far have been smaller.</p></div><div style=\"background: #F7F6F2; border-top: 5px solid #16306E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">You May Be a Candidate If</h2><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 3px; font-size: 15.5px; line-height: 1.45\"><li>Pain has lasted 3 months or more</li><li>Other treatments haven’t helped enough</li><li>You want to avoid or delay surgery</li></ul></div></div></div>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-end; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">9</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 10",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">TAME for the Hand, Wrist &amp; Ankle</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">Small joints can cause big problems. Arthritis in the hand, wrist or ankle can make it hard to grip, write, open jars or walk comfortably.</p>\n<figure style=\"margin: 0; background: #FFFFFF; border: 1px solid #E2DED4; border-radius: 14px; padding: 12px 12px 10px; display: flex; flex-direction: column; gap: 6px\"><img src=\"assets/render-hand.png\" alt=\"Illustration of the hand bones with inflamed finger and thumb joints highlighted in red\" style=\"width: 100%; height: 180px; object-fit: contain; object-position: 50% 50%; display: block\"></figure>\n<div style=\"display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px\">\n<div style=\"background: #F7F6F2; border-radius: 12px; padding: 18px 20px; display: flex; flex-direction: column; gap: 8px; border-left: 0; border-top: 5px solid #16306E\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Hand &amp; Thumb</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">For arthritis in the finger joints and at the base of the thumb. The catheter is usually placed in an artery at the wrist.</p></div>\n<div style=\"background: #F7F6F2; border-radius: 12px; padding: 18px 20px; display: flex; flex-direction: column; gap: 8px; border-left: 0; border-top: 5px solid #16306E\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Wrist</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">For long-lasting wrist pain from arthritis or an old injury. The catheter is usually placed in an artery at the wrist or elbow.</p></div>\n<div style=\"background: #F7F6F2; border-radius: 12px; padding: 18px 20px; display: flex; flex-direction: column; gap: 8px; border-left: 0; border-top: 5px solid #16306E\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Ankle</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">For arthritis and ongoing ankle pain. The catheter is usually placed in an artery at the top of the thigh or near the ankle.</p></div>\n</div>\n<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start\"><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">How It Works</h2><p style=\"margin: 0; font-size: 16px; line-height: 1.5\">Just like GAE, your specialist uses contrast dye and X-ray to find small arteries with extra blood flow around the painful joint. Tiny particles are released into those branches to reduce blood flow to the inflamed tissue.</p><p style=\"margin: 0; font-size: 16px; line-height: 1.5\">Because the arteries in the hand and foot are very small, your specialist uses extra-fine catheters and small amounts of particles.</p></div><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Lower Back Pain</h2><p style=\"margin: 0; font-size: 16px; line-height: 1.5\">Certain kinds of long-lasting lower back pain may also be evaluated for embolization. This use is still being studied. Ask your specialist whether it may be an option for you.</p><div style=\"background: #F7F6F2; border-top: 5px solid #C8231E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Good to Know</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Research on TAME for these joints is at an early stage. Your specialist will talk with you about what is known, the possible benefits and risks, and other treatments.</p></div></div></div>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-start; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">10</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 11",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">Plantar Fasciitis Embolization (PFE)</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">Plantar fasciitis is irritation of the plantar fascia, the thick band of tissue along the bottom of your foot. It often causes sharp heel pain with the first steps in the morning or after sitting.</p>\n<figure style=\"margin: 0; background: #FFFFFF; border: 1px solid #E2DED4; border-radius: 14px; padding: 12px 12px 10px; display: flex; flex-direction: column; gap: 6px\"><img src=\"assets/render-heel.png\" alt=\"Illustration of the foot bones with the painful, inflamed area at the heel highlighted in red\" style=\"width: 100%; height: 290px; object-fit: contain; object-position: 50% 50%; display: block\"><p style=\"margin: 0; font-size: 13px; line-height: 1.4; color: #4A5568; text-align: center\">The painful, inflamed area where the plantar fascia attaches to the heel.</p></figure>\n<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start\"><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Who May Benefit</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Most plantar fasciitis gets better with stretching, supportive shoes, rest and other care. PFE may be an option if you:</p><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 5px; font-size: 15.5px; line-height: 1.45\"><li>Have had heel pain for 6 months or more</li><li>Have tried stretching, shoe inserts, therapy or injections without enough relief</li><li>Want to avoid surgery on the foot</li></ul></div><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">How It Works</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">The catheter is placed in an artery at the top of the thigh or near the ankle. Contrast dye shows the small arteries around the heel with extra blood flow. Particles are released to reduce blood flow to the inflamed tissue.</p><div style=\"background: #F7F6F2; border-top: 5px solid #C8231E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Good to Know</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">PFE is a newer procedure. Early studies have been small, and more research is under way.</p></div></div></div>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-end; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">11</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 12",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">Preparing for Your Procedure</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">Our team will give you instructions before your procedure. Follow them carefully, and call us with any questions.</p>\n<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start\"><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Before Your Procedure</h2><div style=\"display: flex; flex-direction: column; gap: 9px\"><div style=\"display: flex; gap: 12px; align-items: flex-start; font-size: 15.5px; line-height: 1.45\"><span style=\"width: 16px; height: 16px; flex: none; margin-top: 3px; border: 2px solid #16306E; border-radius: 3px; box-sizing: border-box\"></span><span>Tell us about all the medicines you take, including vitamins and supplements. You may be asked to stop blood thinners or some diabetes medicines for a short time. Don’t stop any medicine unless your doctor tells you to.</span></div><div style=\"display: flex; gap: 12px; align-items: flex-start; font-size: 15.5px; line-height: 1.45\"><span style=\"width: 16px; height: 16px; flex: none; margin-top: 3px; border: 2px solid #16306E; border-radius: 3px; box-sizing: border-box\"></span><span>Tell us if you are allergic to contrast dye, iodine or any medicines.</span></div><div style=\"display: flex; gap: 12px; align-items: flex-start; font-size: 15.5px; line-height: 1.45\"><span style=\"width: 16px; height: 16px; flex: none; margin-top: 3px; border: 2px solid #16306E; border-radius: 3px; box-sizing: border-box\"></span><span>You may need blood tests to check your kidney function and blood clotting.</span></div><div style=\"display: flex; gap: 12px; align-items: flex-start; font-size: 15.5px; line-height: 1.45\"><span style=\"width: 16px; height: 16px; flex: none; margin-top: 3px; border: 2px solid #16306E; border-radius: 3px; box-sizing: border-box\"></span><span>Don’t eat or drink before your procedure for as long as our staff tells you.</span></div><div style=\"display: flex; gap: 12px; align-items: flex-start; font-size: 15.5px; line-height: 1.45\"><span style=\"width: 16px; height: 16px; flex: none; margin-top: 3px; border: 2px solid #16306E; border-radius: 3px; box-sizing: border-box\"></span><span>Arrange for an adult to drive you home and stay with you overnight.</span></div></div></div><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">On the Day</h2><div style=\"display: flex; flex-direction: column; gap: 9px\"><div style=\"display: flex; gap: 12px; align-items: flex-start; font-size: 15.5px; line-height: 1.45\"><span style=\"width: 16px; height: 16px; flex: none; margin-top: 3px; border: 2px solid #16306E; border-radius: 3px; box-sizing: border-box\"></span><span>Wear loose, comfortable clothing and leave jewelry at home.</span></div><div style=\"display: flex; gap: 12px; align-items: flex-start; font-size: 15.5px; line-height: 1.45\"><span style=\"width: 16px; height: 16px; flex: none; margin-top: 3px; border: 2px solid #16306E; border-radius: 3px; box-sizing: border-box\"></span><span>Bring your ID, insurance card and list of medicines.</span></div><div style=\"display: flex; gap: 12px; align-items: flex-start; font-size: 15.5px; line-height: 1.45\"><span style=\"width: 16px; height: 16px; flex: none; margin-top: 3px; border: 2px solid #16306E; border-radius: 3px; box-sizing: border-box\"></span><span>An IV line will be placed for fluids and relaxing medicine.</span></div><div style=\"display: flex; gap: 12px; align-items: flex-start; font-size: 15.5px; line-height: 1.45\"><span style=\"width: 16px; height: 16px; flex: none; margin-top: 3px; border: 2px solid #16306E; border-radius: 3px; box-sizing: border-box\"></span><span>You may be asked to point to where it hurts most. This helps guide treatment.</span></div><div style=\"display: flex; gap: 12px; align-items: flex-start; font-size: 15.5px; line-height: 1.45\"><span style=\"width: 16px; height: 16px; flex: none; margin-top: 3px; border: 2px solid #16306E; border-radius: 3px; box-sizing: border-box\"></span><span>After the procedure, you’ll rest for a few hours while we check the puncture site.</span></div></div><div style=\"background: #F7F6F2; border-top: 5px solid #16306E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">We Check Your Insurance First</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Coverage for joint embolization varies, and some plans consider it still being studied. We verify your benefits and explain any costs before your procedure is scheduled.</p></div></div></div>\n<div style=\"background: #16306E; color: #FFFFFF; border-radius: 12px; padding: 20px 24px; display: flex; justify-content: space-between; align-items: center; gap: 20px\"><div style=\"display: flex; flex-direction: column; gap: 4px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 20px\">Questions before your procedure?</p><p style=\"margin: 0; font-size: 15.5px; color: #D9E1F2\">Our team is happy to help. Call us Monday through Friday.</p></div><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 28px; white-space: nowrap\">661-324-4100</p></div>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-start; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">12</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 13",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">After Your Procedure</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">Most people go home a few hours after the procedure. Recovery is usually quick, but relief often builds gradually.</p>\n<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start\"><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">What to Expect</h2><div style=\"display: flex; flex-direction: column\"><div style=\"display: flex; gap: 16px\"><div style=\"display: flex; flex-direction: column; align-items: center; flex: none; width: 20px\"><span style=\"width: 18px; height: 18px; border-radius: 50%; background: #C8231E; border: 3px solid #F2C9C6; box-sizing: border-box\"></span><span style=\"flex: 1; width: 3px; background: #E2DED4\"></span></div><div style=\"display: flex; flex-direction: column; gap: 4px; padding-bottom: 16px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Day of procedure</p><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Rest at home. Keep the puncture site clean and dry. An adult should drive you home and stay with you overnight.</p></div></div><div style=\"display: flex; gap: 16px\"><div style=\"display: flex; flex-direction: column; align-items: center; flex: none; width: 20px\"><span style=\"width: 18px; height: 18px; border-radius: 50%; background: #C8231E; border: 3px solid #F2C9C6; box-sizing: border-box\"></span><span style=\"flex: 1; width: 3px; background: #E2DED4\"></span></div><div style=\"display: flex; flex-direction: column; gap: 4px; padding-bottom: 16px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">First few days</p><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Some soreness in the joint and a small bruise at the puncture site are normal. Short walks are fine. Avoid heavy lifting and hard exercise.</p></div></div><div style=\"display: flex; gap: 16px\"><div style=\"display: flex; flex-direction: column; align-items: center; flex: none; width: 20px\"><span style=\"width: 18px; height: 18px; border-radius: 50%; background: #C8231E; border: 3px solid #F2C9C6; box-sizing: border-box\"></span><span style=\"flex: 1; width: 3px; background: #E2DED4\"></span></div><div style=\"display: flex; flex-direction: column; gap: 4px; padding-bottom: 16px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Weeks 1 to 4</p><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Pain relief often starts gradually. Return to your usual activities as your specialist advises.</p></div></div><div style=\"display: flex; gap: 16px\"><div style=\"display: flex; flex-direction: column; align-items: center; flex: none; width: 20px\"><span style=\"width: 18px; height: 18px; border-radius: 50%; background: #C8231E; border: 3px solid #F2C9C6; box-sizing: border-box\"></span></div><div style=\"display: flex; flex-direction: column; gap: 4px; padding-bottom: 0px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 17px; color: #16306E\">Months 1 to 3</p><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Follow-up visits track your progress. The full effect may take several weeks to a few months.</p></div></div></div></div><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Caring for the Puncture Site</h2><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 5px; font-size: 15.5px; line-height: 1.45\"><li>Keep the bandage on and the site dry for 24 hours, or as instructed</li><li>You can shower after 24 hours. Avoid baths, hot tubs and swimming until the site heals</li><li>A small bruise or a pea-sized lump is normal</li><li>Don’t lift anything heavy with the arm or leg used for the puncture for a few days</li></ul><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Managing Discomfort</h2><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 5px; font-size: 15.5px; line-height: 1.45\"><li>Some soreness in the treated joint for a few days is normal</li><li>Use the pain reliever your specialist recommends</li><li>Ice the joint for 15 to 20 minutes at a time if advised</li></ul><div style=\"background: #F7F6F2; border-top: 5px solid #16306E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Keep Moving</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">As pain eases, gentle exercise or physical therapy helps build strength and keep the joint moving. Ask your specialist when to start.</p></div></div></div>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-end; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">13</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 14",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">Risks &amp; When to Call</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">Embolization is done through a tiny puncture, not surgery, but like any procedure it has risks. Your specialist will talk with you about them before you decide.</p>\n<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start\"><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #C8231E\">Possible Risks and Complications</h2><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 5px; font-size: 15.5px; line-height: 1.45\"><li>Bruising or bleeding at the puncture site</li><li>Temporary skin color change or tenderness over the treated area, which usually fades in days to weeks</li><li>A short-term increase in joint pain</li><li>Allergic reaction to contrast dye</li><li>Infection</li><li>Injury to the artery</li><li>Strain on the kidneys from contrast dye, mainly in people with kidney disease</li><li>Numbness or tingling near the treated area, usually temporary</li><li>Rarely, particles reaching nearby tissue, which can cause skin sores or tissue damage</li></ul></div><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><div style=\"border: 2px solid #C8231E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px; background: #FFFFFF\"><div style=\"display: flex; align-items: center; gap: 12px\"><div style=\"width: 34px; height: 34px; flex: none; border-radius: 8px; background: #C8231E; color: #FFFFFF; display: flex; align-items: center; justify-content: center; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 22px\">!</div><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #C8231E\">When to Call Your Doctor</h2></div><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Call <b>661-324-4100</b> right away if you have:</p><ul style=\"margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 5px; font-size: 15.5px; line-height: 1.45\"><li>A lump at the puncture site that grows, throbs or pulses</li><li>Fever of 100.4°F (38°C) or higher, or chills</li><li>Increasing redness, warmth, pain or drainage at the puncture site</li><li>Skin over the treated area that turns dark, blisters or opens</li><li>Numbness, tingling, coldness or color change in your arm, hand, leg or foot</li><li>Joint pain that gets much worse instead of better</li></ul></div><div style=\"background: #C8231E; color: #FFFFFF; border-radius: 12px; padding: 16px 20px; display: flex; flex-direction: column; gap: 6px\"><p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 18px\">Call 911 if you have</p><p style=\"margin: 0; font-size: 15.5px; line-height: 1.45\">If the puncture site bleeds, lie down and press firmly on it. Call 911 if it doesn’t stop after 10 minutes or swelling grows quickly. Also call 911 for chest pain, trouble breathing or signs of a stroke (face drooping, arm weakness, trouble speaking).</p></div></div></div>\n<p style=\"margin: 0; font-size: 13px; line-height: 1.4; color: #4A5568\">For urgent concerns after hours, call 661-324-4100.</p>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-start; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">14</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Page 15",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<header style=\"background: #16306E; color: #FFFFFF; padding: 40px 56px 24px; display: flex; flex-direction: column; gap: 6px; border-bottom: 8px solid #C8231E\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 3px; text-transform: uppercase; color: #F2A7A3\">Joint &amp; tendon pain guide</p>\n<h1 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 38px; line-height: 1.1\">Self-Care for Your Joints</h1>\n</header>\n<main style=\"flex: 1; min-height: 0; padding: 30px 56px 0; display: flex; flex-direction: column; gap: 18px\">\n\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5; font-weight: 600; color: #16306E\">What you do every day matters. Self-care can ease pain on its own and help you get the most from any treatment.</p>\n<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start\"><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Stay Active</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Low-impact activities like walking, swimming and cycling keep joints moving without extra strain. Start slowly and build up.</p><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Manage Your Weight</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Extra weight adds pressure to the hips, knees and feet. Even a small weight loss can ease that pressure.</p><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Build Strength</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Strong muscles support and protect your joints. A physical therapist can show you exercises that are safe for you.</p></div><div style=\"display: flex; flex-direction: column; gap: 12px; min-width: 0\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Use Heat and Cold</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Heat can loosen stiff joints. Cold can calm swelling after activity. Use either for 15 to 20 minutes at a time, with a cloth between your skin and the pack.</p><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Protect Your Joints</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Wear supportive shoes, use tools with large grips and pace yourself. For heel pain, stretch your calf and the bottom of your foot before your first steps in the morning.</p></div></div>\n<div style=\"background: #F7F6F2; border-top: 5px solid #16306E; border-radius: 12px; padding: 18px 22px; display: flex; flex-direction: column; gap: 10px\"><h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 21px; line-height: 1.2; color: #16306E\">Track Your Progress</h2><p style=\"margin: 0; font-size: 15.5px; line-height: 1.5\">Rate your pain each week and note what you were able to do. Bring this to your follow-up visits.</p><table style=\"width: 100%; border-collapse: collapse; background: #FFFFFF; border: 1px solid #E2DED4\"><colgroup><col style=\"width: 22%\"><col style=\"width: 20%\"><col></colgroup><thead><tr><th style=\"text-align: left; padding: 8px 10px; font-size: 13px; font-family: 'Montserrat', sans-serif; font-weight: 700; color: #FFFFFF; background: #16306E\">Date</th><th style=\"text-align: left; padding: 8px 10px; font-size: 13px; font-family: 'Montserrat', sans-serif; font-weight: 700; color: #FFFFFF; background: #16306E\">Pain (0–10)</th><th style=\"text-align: left; padding: 8px 10px; font-size: 13px; font-family: 'Montserrat', sans-serif; font-weight: 700; color: #FFFFFF; background: #16306E\">What I could do this week</th></tr></thead><tbody><tr><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td></tr><tr><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td></tr><tr><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td></tr><tr><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td></tr><tr><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td></tr><tr><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td><td style=\"height: 30px; border-bottom: 1px solid #E2DED4; padding: 0 10px\"></td></tr></tbody></table></div>\n\n</main>\n<footer style=\"padding: 14px 56px 26px; display: flex; justify-content: flex-end; gap: 14px; font-size: 12px; color: #4A5568\">\n<span style=\"font-weight: 700; color: #16306E\">15</span><span>Advanced Joint Pain &amp; Vascular Center</span>\n</footer>\n</div>"
   },
   {
    "label": "Back cover",
    "w": 816,
    "h": 1056,
    "html": "<div style=\"width: 816px; height: 1056px; box-sizing: border-box; background: #FFFEFB; color: #1B2440; font-family: 'Public Sans', sans-serif; display: flex; flex-direction: column\">\n<div style=\"height: 14px; background: #C8231E\"></div>\n<div style=\"flex: 1; padding: 52px 56px 32px; display: flex; flex-direction: column; gap: 26px\">\n<div style=\"display: flex; flex-direction: column; gap: 10px\">\n<h2 style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 34px; line-height: 1.15; color: #16306E\">Getting Back to What You Love</h2>\n<p style=\"margin: 0; font-size: 18px; line-height: 1.5\">Joint and tendon pain doesn’t have to be something you just live with. Talk with your doctor about your options, keep up with self-care and come to your follow-up visits. We’re here to help at every step.</p>\n</div>\n<div style=\"background: #16306E; color: #FFFFFF; border-radius: 16px; padding: 24px 28px; display: flex; align-items: center; gap: 22px\">\n<img src=\"assets/dr-kumar.jpg\" alt=\"Dr. Vinod Kumar\" style=\"width: 112px; height: 112px; border-radius: 50%; object-fit: cover; border: 4px solid #FFFFFF; flex: none; display: block\">\n<div style=\"display: flex; flex-direction: column; gap: 6px\">\n<p style=\"margin: 0; font-size: 13px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: #F2A7A3\">Meet your specialist</p>\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 24px\">Dr. Vinod Kumar</p>\n<p style=\"margin: 0; font-size: 15.5px; line-height: 1.45; color: #D9E1F2\">Interventional cardiovascular specialist with more than 30 years of experience. Trained in joint embolization in Tokyo with Dr. Yuji Okuno, a pioneer of embolization for joint pain.</p>\n</div>\n</div>\n<div style=\"display: grid; grid-template-columns: 1.2fr 1fr; gap: 28px; align-items: start\">\n<div style=\"display: flex; flex-direction: column; gap: 8px; font-size: 17px; line-height: 1.5\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 20px; color: #16306E\">Advanced Joint Pain &amp; Vascular Center</p>\n<p style=\"margin: 0; font-weight: 700\">{{LOCATION_NAME}}</p>\n<p style=\"margin: 0\">{{STREET}}<br>{{CITY_STATE_ZIP}}</p>\n<p style=\"margin: 0\">{{HOURS}}</p>\n<p style=\"margin: 6px 0 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 26px; color: #C8231E\">661-324-4100</p>\n<p style=\"margin: 0\">Fax 661-324-4600 · heartandleg.com</p>\n</div>\n<div style=\"background: #FFFFFF; border: 1px solid #E2DED4; border-radius: 14px; padding: 16px; display: flex; align-items: center; gap: 16px\">\n<img src=\"assets/qr-testimonial.png\" alt=\"QR code linking to a patient testimonial video\" style=\"width: 112px; height: 112px; flex: none; display: block\">\n<div style=\"display: flex; flex-direction: column; gap: 4px\">\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 800; font-size: 13px; letter-spacing: 2px; text-transform: uppercase; color: #C8231E\">Scan to watch</p>\n<p style=\"margin: 0; font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 18px; line-height: 1.25; color: #16306E\">Hear a patient’s story</p>\n<p style=\"margin: 0; font-size: 13px; color: #4A5568\">Runtime 6:30 · Individual results vary</p>\n</div>\n</div>\n</div>\n<div style=\"flex: 1\"></div>\n<div style=\"display: flex; justify-content: space-between; align-items: flex-end; gap: 24px; border-top: 1px solid #E2DED4; padding-top: 20px\">\n<p style=\"margin: 0; font-size: 12.5px; line-height: 1.5; color: #4A5568; max-width: 430px\">This booklet is not intended as a substitute for professional medical care. Only your doctor can diagnose and treat a medical problem. Individual results vary; not everyone is a candidate for every procedure.</p>\n<img src=\"assets/logo-tall-nodivision.png\" alt=\"Advanced Joint Pain &amp; Vascular Center logo\" style=\"width: 150px; height: 120px; object-fit: contain; flex: none\">\n</div>\n</div>\n</div>"
   }
